def longest_common_prefix(strings):
    if not strings:
        return ''

    if len(strings) == 1:
        return strings[0]

    min_len = min(len(s) for s in strings)

    for i in range(min_len):
        char = strings[0][i]
        for s in strings[1:]:
            if s[i] != char:
                return strings[0][:i]

    return strings[0][:min_len]
```

